SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(12*10^9);Alarm(450);tt:=Cputime();AttachSpec("work/deg10/shared/mdmagma/v2/mdmagma.spec");X:=MDX11(2,28,GF(3));FF:=FunctionField(Curve(X));F0,mp:=AlgorithmicFunctionField(FF);F:=RationalExtensionRepresentation(F0);assert Genus(F) eq 25;bc:=[F!mp(z):z in X`_coordinates];b,c:=Explode(bc);d:=b*(1-b-c);E:=EllipticCurve([F|0,c,0,d,0]);cs:=Poles(jInvariant(E));assert {*Degree(p):p in cs*} eq {*1^^12,2^^6,3^^4,6^^2*};cp:=[p:p in cs|Degree(p) eq 3];sig:=[[Valuation(v,p):v in[b,d,c^2-4*d]]:p in cp];ss:=Sort(Setseq(Seqset(sig)));assert #ss eq 2;blocks:=[Divisor(p):p in cs|Degree(p) ne 3] cat [&+[Divisor(cp[i]):i in[1..4]|sig[i] eq s]:s in ss];assert {*Degree(D):D in blocks*} eq {*1^^12,2^^6,6^^4*};base:=Divisor([p:p in cs|Degree(p) eq 1][1]);print "Y228_CANDIDATE_PICARD_START",Cputime(tt);G,_,phi:=ClassGroup(F:ReductionDivisor:=base,Proof:=false);bg:=phi(base);qg:=[phi(D)-Degree(D)*bg:D in blocks];H:=sub<G|qg>;print "Y228_CANDIDATE_PICARD_GROUPS",Invariants(G),Invariants(H),Cputime(tt);Write("work/deg10/continuation_20261031b/Y228_shared/Picard3_candidate_only.m",Sprint([*[Eltseq(v):v in Rows(RelationMatrix(G))],[Eltseq(v):v in qg],Invariants(H),[Degree(D):D in blocks]*]):Overwrite:=true);print "D31B_Y228_PICARD3_CANDIDATE_ONLY_COMPLETE",Cputime(tt);quit;
